//! The differential test for the post-processing step: logits in, the reference's `Answer` out.
//!
//! The fixture is generated by `scripts/make-decide-fixture.py`, which calls the reference's **own**
//! `clamp_temperature`, `temp_bucket` and `confidence_from_probs` — not a restatement of their
//! formulas. If the reference changes, the fixture changes with it; a port that copied the formulas
//! would keep passing while the reference moved.
//!
//! What this pins, and why each is worth a case:
//!
//! * the **temperature actually used** and whether it was clamped (F3/F4 — the blocker that would
//!   otherwise publish a 0.24 as 0.99);
//! * the **softmax**, including at the ~3000-magnitude act logits, where a missing max-subtraction
//!   overflows and nowhere else;
//! * the **confidence formula** at the maximum-entropy case, where a wrong `log(k)` still looks
//!   plausible, and at a zero probability, where a missing `1e-12` clip yields NaN;
//! * the **per-type value rules**, because `score` reports an expectation and `noul` reports `p[1]`;
//! * the **`noul` confidence OVERRIDE** (`max(p[1], 1-p[1])`), proven distinct from the entropy form
//!   by asserting on the fixture's own `entropy_confidence` for a case where they differ;
//! * **F10** — the label is identical across six in-range temperatures while the probabilities move.
//!
//! A test may fail loudly and indexes small fixed slices it builds itself.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::cast_precision_loss,
    clippy::single_char_lifetime_names
)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use laya_abi::{Question, QuestionType};
use laya_head::decide::{confidence_from_probs, qtype_index, softmax, temp_bucket};
use laya_head::safetensors::{HeadConfig, SafetensorsFile};
use serde::Deserialize;

/// The fixture path, resolved from the crate root so it does not depend on the working directory.
fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/decide.json")
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    cases: Vec<Case>,
    f10: Vec<F10>,
}

#[derive(Debug, Deserialize)]
struct Meta {
    temp_bucket_of_choice_11: String,
    temp_bucket_of_choice_2: String,
}

#[derive(Debug, Deserialize)]
struct Case {
    label: String,
    logits: Vec<f64>,
    qtype: usize,
    k: usize,
    configured_temperature: f64,
    temperature_used: f64,
    temperature_was_clamped: bool,
    bucket: String,
    probabilities: Vec<f64>,
    confidence: f64,
    value: serde_json::Value,
    entropy_confidence: f64,
    raw_logit_gap: f64,
}

#[derive(Debug, Deserialize)]
struct F10 {
    temperature_configured: f64,
    temperature_used: f64,
    probabilities: Vec<f64>,
    value: i64,
}

fn load() -> Fixture {
    let text = std::fs::read_to_string(fixture()).expect("fixture must exist");
    serde_json::from_str(&text).expect("fixture must parse")
}

/// A `HeadConfig` that carries only what `decide_with` reads: the temperature tables.
///
/// Built directly rather than loaded from the checkpoint so the test does not depend on the 106 MB
/// file for cases that are about arithmetic. The real config is exercised separately by the
/// metadata test in `safetensors.rs`, and the end-to-end path by `decide_uses_the_real_checkpoint`.
fn config_for(cases: &[Case]) -> HeadConfig {
    let mut by_options = BTreeMap::new();
    let mut temperature = vec![1.0_f64; 3];
    for c in cases {
        // The fixture records the bucket key and the configured value for that bucket; the base
        // per-type array holds the real checkpoint's three values.
        by_options.insert(c.bucket.clone(), c.configured_temperature);
        if c.qtype < temperature.len() {
            temperature[c.qtype] = c.configured_temperature;
        }
    }
    temperature[0] = 1.636_903_047_561_645_5;
    temperature[1] = 1.251_430_034_637_451_2;
    temperature[2] = 1.983_399_510_383_606;
    HeadConfig {
        encoder: "fixture".to_string(),
        head_layers: 2,
        max_len: 512,
        head_max_len: 192,
        max_prefixes: 255,
        temperature,
        temperature_by_options: by_options,
    }
}

/// The reference's post-processing, re-derived from the fixture's own inputs, so the assertions are
/// against **this test's** arithmetic as well as the fixture's numbers.
///
/// The per-type confidence rule is reproduced here INCLUDING the `noul` override. Getting this
/// wrong is exactly what this test caught: the first version of both this helper and the fixture
/// used the entropy form for every type, while the reference overrides it for `noul`
/// (`agent.py:360`) — and the Rust implementation was the one that was right.
fn recompute(c: &Case) -> (Vec<f64>, f64) {
    let z: Vec<f64> = c
        .logits
        .iter()
        .take(c.k)
        .map(|&l| l / c.temperature_used)
        .collect();
    let probs = softmax(&z);
    let entropy = confidence_from_probs(&probs, c.k);
    let confidence = if c.qtype == qtype_index(QuestionType::Noul) {
        // max(p[1], 1 - p[1]): a two-outcome belief has a direct confidence.
        let p_yes = probs.get(1).copied().unwrap_or(0.0);
        p_yes.max(1.0 - p_yes)
    } else {
        entropy
    };
    (probs, confidence)
}

/// The bucket key is the reference's, at both ends of its range.
#[test]
fn temp_bucket_matches_the_reference() {
    let f = load();
    assert_eq!(f.meta.temp_bucket_of_choice_11, "choice:11+");
    assert_eq!(f.meta.temp_bucket_of_choice_2, "choice:2");
    assert_eq!(temp_bucket(QuestionType::Choice, 11), "choice:11+");
    assert_eq!(temp_bucket(QuestionType::Choice, 2), "choice:2");
    assert_eq!(temp_bucket(QuestionType::Score, 4), "score:3-5");
    assert_eq!(temp_bucket(QuestionType::Noul, 2), "noul:2");
    // Boundaries: the sizes switch at 2/3, 5/6 and 10/11.
    for (k, want) in [
        (1, "choice:2"),
        (2, "choice:2"),
        (3, "choice:3-5"),
        (5, "choice:3-5"),
        (6, "choice:6-10"),
        (10, "choice:6-10"),
        (11, "choice:11+"),
        (255, "choice:11+"),
    ] {
        assert_eq!(temp_bucket(QuestionType::Choice, k), want, "k={k}");
    }
}

/// `qtype_index` is the measured `QTYPES`, not the order the names happen to read.
#[test]
fn qtype_index_matches_the_reference() {
    assert_eq!(
        qtype_index(QuestionType::Choice),
        0,
        "QTYPES['choice'] == 0"
    );
    assert_eq!(qtype_index(QuestionType::Score), 1, "QTYPES['score'] == 1");
    assert_eq!(qtype_index(QuestionType::Noul), 2, "QTYPES['noul'] == 2");
}

/// Every case reproduces the reference's probabilities and confidence.
#[test]
fn the_post_processing_matches_the_reference() {
    let f = load();
    let mut worst = 0.0_f64;
    for c in &f.cases {
        let (probs, confidence) = recompute(c);
        assert_eq!(
            c.probabilities.len(),
            c.k,
            "{}: the fixture has {} probabilities for k={}",
            c.label,
            c.probabilities.len(),
            c.k
        );
        for (index, (got, want)) in probs.iter().zip(&c.probabilities).enumerate() {
            let diff = (got - want).abs();
            worst = worst.max(diff);
            assert!(
                diff < 1e-12,
                "{}: probability[{index}] {got} vs the reference {want} (diff {diff:e})",
                c.label
            );
        }
        let diff = (confidence - c.confidence).abs();
        assert!(
            diff < 1e-12,
            "{}: confidence {confidence} vs the reference {} (diff {diff:e})",
            c.label,
            c.confidence
        );
    }
    println!("  worst probability/confidence difference vs the reference: {worst:e}");
}

/// The temperature selection: the clamped value is the one used, and the flag says so.
#[test]
fn the_temperature_used_is_the_clamped_one() {
    let f = load();
    let cfg = config_for(&f.cases);
    for c in &f.cases {
        let want = laya_head::clamp_temperature(c.configured_temperature);
        assert!(
            (want - c.temperature_used).abs() < 1e-15,
            "{}: clamp_temperature({}) = {want}, the fixture used {}",
            c.label,
            c.configured_temperature,
            c.temperature_used
        );
        assert_eq!(
            laya_head::temperature_was_clamped(c.configured_temperature),
            c.temperature_was_clamped,
            "{}: the clamped flag disagrees",
            c.label
        );
    }
    // The whole point of F3: exactly one bucket in the real config is out of range, and the clamp
    // is what saves it. 0.10058 would multiply logits ~10x.
    assert!(cfg.temperature_by_options.contains_key("choice:11+"));
}

/// The huge-logit case, where a softmax that does not subtract the max overflows.
#[test]
fn the_softmax_survives_the_act_logit_magnitude() {
    let f = load();
    let case = f
        .cases
        .iter()
        .find(|c| c.label == "choice_k4_huge_logits")
        .expect("the huge-logit case must be in the fixture");
    let (probs, _) = recompute(case);
    assert!(
        probs.iter().all(|p| p.is_finite()),
        "the softmax produced a non-finite probability: {probs:?}"
    );
    let sum: f64 = probs.iter().sum();
    assert!((sum - 1.0).abs() < 1e-12, "probabilities sum to {sum}");
}

/// The reported `logit_gap` is the reference's `top1 - top2` over the raw logits.
///
/// This is the quantity the spec's F8 called "the margin", and it is asserted against the fixture's
/// own `raw_logit_gap` so the name in the port is pinned to the reference's arithmetic. The ROUTING
/// margin is a different quantity in probability space and lives in `laya-core`'s payload.
#[test]
fn the_logit_gap_is_the_raw_top1_minus_top2() {
    let f = load();
    for c in &f.cases {
        let mut sorted = c.logits.clone();
        sorted.sort_by(f64::total_cmp);
        let want = if c.k >= 2 {
            sorted[sorted.len() - 1] - sorted[sorted.len() - 2]
        } else {
            c.logits[0]
        };
        assert!(
            (want - c.raw_logit_gap).abs() < 1e-12,
            "{}: the fixture's raw_logit_gap {} is not top1-top2 = {want}",
            c.label,
            c.raw_logit_gap
        );
    }
    println!("  logit gap checked over {} cases", f.cases.len());
}

/// The `noul` confidence is the reference's OVERRIDE, not the entropy form.
///
/// Asserted against the fixture's own `entropy_confidence` rather than restating the formula: the
/// test only means something if the two forms are actually different for the case it picks.
#[test]
fn the_noul_confidence_overrides_the_entropy_form() {
    let f = load();
    let mut proven_different = 0;
    for c in f.cases.iter().filter(|c| c.qtype == 2 && c.k >= 2) {
        let p_yes = c.probabilities[1];
        let want = p_yes.max(1.0 - p_yes);
        assert!(
            (want - c.confidence).abs() < 1e-12,
            "{}: noul confidence {} is not max(p[1], 1-p[1]) = {want}",
            c.label,
            c.confidence
        );
        // The control: for at least one case the two forms must disagree, or this test would pass
        // even if the port wrongly used the entropy form everywhere.
        if (c.entropy_confidence - c.confidence).abs() > 1e-6 {
            proven_different += 1;
        }
    }
    assert!(
        proven_different > 0,
        "no noul case has a confidence that differs from the entropy form, so this test does not \
         actually distinguish the override from the default"
    );
    println!("  noul cases where the override differs from the entropy form: {proven_different}");
}

/// The `score` value is the expectation over levels, which may fall between them.
#[test]
fn the_score_is_the_expected_level() {
    let f = load();
    for c in f.cases.iter().filter(|c| c.qtype == 1) {
        let want: f64 = c
            .probabilities
            .iter()
            .enumerate()
            .map(|(level, &p)| level as f64 * p)
            .sum();
        let got = c.value.as_f64().expect("a score value must be a number");
        assert!(
            (got - want).abs() < 1e-9,
            "{}: score {got} vs the expectation {want}",
            c.label
        );
        // A fractional score is the point of the type, so at least one case must exercise it.
        assert!(
            (got.fract()).abs() > f64::EPSILON || c.label.contains("even"),
            "{}: the score landed exactly on a level, which does not exercise the fractional case",
            c.label
        );
    }
}

/// F10: the same logits under six in-range temperatures give ONE label and DIFFERENT probabilities.
///
/// This is the invariant the spec singles out, and the two halves are what make it a real test: a
/// port that ignored temperature entirely would pass the first half, and one that let temperature
/// move the label would fail it — but only the second half shows the temperatures were applied at
/// all rather than silently dropped.
#[test]
fn the_label_does_not_depend_on_temperature() {
    let f = load();
    assert!(f.f10.len() >= 2, "the fixture needs several temperatures");

    let values: Vec<i64> = f.f10.iter().map(|c| c.value).collect();
    assert!(
        values.windows(2).all(|w| w[0] == w[1]),
        "the label changed across temperatures: {values:?}"
    );

    // Every temperature must actually have been applied: at least two cases must differ somewhere
    // in their probability vector, and the extremes must differ by more than rounding.
    let first = &f.f10[0].probabilities;
    let last = &f.f10[f.f10.len() - 1].probabilities;
    let spread = first
        .iter()
        .zip(last)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f64, f64::max);
    assert!(
        spread > 1e-3,
        "the probabilities barely moved across the temperature range (max spread {spread:e}), so \
         this test would pass even if temperature were ignored"
    );

    // And the Rust port must reproduce each of those probability vectors too, which is what ties
    // this test to the implementation rather than to the fixture.
    for c in &f.f10 {
        let z: Vec<f64> = [0.30, 0.10, -0.20, 0.05]
            .iter()
            .map(|&l| l / c.temperature_used)
            .collect();
        let probs = softmax(&z);
        for (index, (got, want)) in probs.iter().zip(&c.probabilities).enumerate() {
            assert!(
                (got - want).abs() < 1e-12,
                "T={}: probability[{index}] {got} vs {}",
                c.temperature_configured,
                want
            );
        }
        let argmax = probs
            .iter()
            .enumerate()
            .max_by(|(_, a), (_, b)| a.total_cmp(b))
            .map_or(0, |(i, _)| i);
        assert_eq!(
            i64::try_from(argmax).unwrap_or(-1),
            c.value,
            "T={}: the port's argmax {argmax} disagrees with the reference's {}",
            c.temperature_configured,
            c.value
        );
    }
    println!(
        "  F10: one label across {} temperatures, probability spread {spread:.4}",
        f.f10.len()
    );
}

/// The degenerate `k = 1` case the reference cannot express: a single marker has confidence 1.0.
#[test]
fn a_single_marker_has_full_confidence() {
    // The reference raises IndexError for a k=1 noul and returns 1.0 for k=1 from
    // `confidence_from_probs`, so only the latter is a behaviour to match.
    assert!((confidence_from_probs(&[1.0], 1) - 1.0).abs() < f64::EPSILON);
    assert!((confidence_from_probs(&[], 1) - 1.0).abs() < f64::EPSILON);
    // And with k >= 2 it is the entropy form: an even split has zero confidence.
    let even = confidence_from_probs(&[0.5, 0.5], 2);
    assert!(
        even.abs() < 1e-12,
        "an even split must be 0 confidence, got {even}"
    );
}

/// A question with no markers is refused by name rather than dividing by zero.
#[test]
fn a_question_with_no_markers_is_refused() {
    let f = load();
    let cfg = config_for(&f.cases);
    let question = Question::choice("q0", "pick one", ["a", "b"]);
    let Ok(checkpoint) = SafetensorsFile::open(Path::new(REAL_HEAD)) else {
        eprintln!("SKIP: checkpoint absent");
        return;
    };
    let head = laya_head::forward::Head::load(&checkpoint).expect("load");
    // A well-formed hidden state but zero markers: the error must name the question.
    let hidden = vec![0.0_f32; 4 * head.d()];
    let err = head
        .decide(&cfg, &question, &hidden, &[], &[])
        .expect_err("zero markers must be refused");
    let text = err.to_string();
    assert!(
        text.contains("q0"),
        "the error must name the question: {text}"
    );
    assert!(
        text.contains("no option markers"),
        "the error must say what was wrong: {text}"
    );
}

/// The end-to-end path: the REAL checkpoint, a real hidden state, a real answer.
///
/// This is the test that would catch a wiring mistake — a `HeadConfig` from the real file, the real
/// weights, and the temperature table read from metadata rather than supplied by a test.
#[test]
fn decide_uses_the_real_checkpoint_and_config() {
    let Ok(checkpoint) = SafetensorsFile::open(Path::new(REAL_HEAD)) else {
        eprintln!("SKIP: checkpoint absent");
        return;
    };
    let cfg = HeadConfig::from_metadata(checkpoint.metadata()).expect("laya.config must parse");
    let head = laya_head::forward::Head::load(&checkpoint).expect("load");
    let d = head.d();

    // A choice question with 3 options: 3 markers, one row each.
    let question = Question::choice("pick", "which?", ["alpha", "beta", "gamma"]);
    let seq = 8;
    // A deterministic, non-degenerate hidden state: a fixed pattern, no RNG (a test that depends on
    // a seed is a test that can flake).
    let hidden: Vec<f32> = (0..seq * d)
        .map(|i| ((i % 97) as f32 / 97.0) - 0.5)
        .collect();
    let marker_pos = vec![1, 3, 5];
    let marker_mask = vec![true, true, true];

    let decision = head
        .decide(&cfg, &question, &hidden, &marker_pos, &marker_mask)
        .expect("decide must succeed");

    // The temperature came from the REAL config's `choice:3-5` bucket, clamped.
    assert!(decision.temperature >= laya_head::TEMP_MIN);
    assert!(decision.temperature <= laya_head::TEMP_MAX);
    assert_eq!(decision.bucket, "choice:3-5");
    assert_eq!(decision.answer.probabilities.len(), 3);
    assert_eq!(decision.answer.options, vec!["alpha", "beta", "gamma"]);
    assert!(question.options.contains(&decision.answer.value));
    assert!((0.0..=1.0).contains(&decision.answer.confidence));
    let sum: f64 = decision.answer.probabilities.iter().sum();
    assert!((sum - 1.0).abs() < 1e-9, "probabilities sum to {sum}");
    // The act probability is inert in this checkpoint, which is why it is not on `Answer`.
    assert!((0.0..=1.0).contains(&decision.act_probability));
    println!(
        "  real checkpoint: chose {:?}, T={:.4} (clamped={}), confidence={:.4}, logit_gap={:.4}",
        decision.answer.value,
        decision.temperature,
        decision.bucket_clamped,
        decision.answer.confidence,
        decision.logit_gap
    );
}

/// The real checkpoint's temperature array is in range, and only `choice:11+` is not.
///
/// This is the measured fact the spec records; asserting it here means a checkpoint swap that
/// changes it fails a test rather than silently moving every confidence.
#[test]
fn the_real_temperatures_are_as_measured() {
    let Ok(checkpoint) = SafetensorsFile::open(Path::new(REAL_HEAD)) else {
        eprintln!("SKIP: checkpoint absent");
        return;
    };
    let cfg = HeadConfig::from_metadata(checkpoint.metadata()).expect("laya.config must parse");
    // [choice, score, noul], per QTYPES — NOT the order the names read.
    assert_eq!(cfg.temperature.len(), 3);
    assert!(
        (cfg.temperature[0] - 1.636_903_047_561_645_5).abs() < 1e-6,
        "choice"
    );
    assert!(
        (cfg.temperature[1] - 1.251_430_034_637_451_2).abs() < 1e-6,
        "score"
    );
    assert!(
        (cfg.temperature[2] - 1.983_399_510_383_606).abs() < 1e-6,
        "noul"
    );
    for (index, value) in cfg.temperature.iter().enumerate() {
        assert!(
            !laya_head::temperature_was_clamped(*value),
            "temperature[{index}] = {value} is already in range, as measured"
        );
    }
    let out_of_range: Vec<&String> = cfg
        .temperature_by_options
        .iter()
        .filter(|(_, v)| laya_head::temperature_was_clamped(**v))
        .map(|(k, _)| k)
        .collect();
    assert_eq!(
        out_of_range,
        vec![&"choice:11+".to_string()],
        "exactly one bucket is out of range, and it is choice:11+"
    );
    let raw = cfg
        .temperature_by_options
        .get("choice:11+")
        .copied()
        .unwrap_or(0.0);
    assert!((raw - 0.100_58).abs() < 1e-4, "raw choice:11+ = {raw}");
    assert!((laya_head::clamp_temperature(raw) - laya_head::TEMP_MIN).abs() < 1e-15);
}

/// The real checkpoint, where the fixture lives.
const REAL_HEAD: &str = "/projects/_tmp/laya-gguf/laya-head.safetensors";
